cd /private/tmp/claude-501/-Users-maparent-OpenSource-discourse-graph/22394fcc-367e-49a1-a67d-b152c6e91dce/scratchpad && python3 - <<'EOF'
p='dg-accounts-identities.dot'; s=open(p).read()
old='''  { rank=same; L_space; L_person; L_agent; L_none; }
  { rank=same; C_S; C_G; C_E; }
'''
new='''  { rank=same; L_space; L_person; L_agent; L_none; }
  { rank=same; C_S; C_G; C_E; }
  // Invisible links inside each column fix its top-to-bottom order.
  L_space -> L_agent -> L_person -> L_none [style=invis];
  C_S -> C_G -> C_E [style=invis];
'''
assert old in s; s=s.replace(old,new)
s=s.replace("// Declaration order sets the vertical order; logins follow their principals to avoid crossings.\n",
 "// Invisible links inside the first and last columns fix their vertical order, so that the long\n// everyone -> public content arrow runs along the bottom instead of crossing the other links.\n")
open(p,'w').write(s)
EOF
dot -Tsvg dg-accounts-identities.dot -o dg-accounts-identities.svg && dot -Tpng -Gdpi=150 dg-accounts-identities.dot -o dg-accounts-identities-dot.png && echo ok
